SELECT member_id AS memberId, role_id AS roleId, login_id AS loginId, password, name, nickname, email, phone, withdrawn, withdrawn_at AS withdrawnAt, created_at AS createdAt, updated_at AS updatedAt
FROM member
AND ( login_id LIKE CONCAT('%', #{keyword}, '%') OR name LIKE CONCAT('%', #{keyword}, '%') OR nickname LIKE CONCAT('%', #{keyword}, '%') OR email LIKE CONCAT('%', #{keyword}, '%') )
AND withdrawn = #{withdrawn}
AND role_id = #{roleId}
ORDER BY member_id DESC
LIMIT #{size} OFFSET #{offset}

